struct kz_fiber {
    kz_fiber* parent;
    kz_fiber* next;
    int (*step)(kz_fiber*);
    KzValue* slots;
    size_t slot_count;
    long* guards;
    size_t guard_count;
    KzValue args;
    KzValue ret;
    long fuel;
    int pc;
    int done;
    int cancelled;
    const char* name;
};

