static inline KzValue kz_record_new_Token(size_t n, KzValue* v, const char** k) {
    (void)n; (void)v; (void)k;
    static const char* _keys[5] = { "kind", "text", "line", "col", "at" };
    KzValue _vals[5];
    _vals[0] = kz_nil();
    _vals[1] = kz_nil();
    _vals[2] = kz_nil();
    _vals[3] = kz_nil();
    _vals[4] = kz_nil();
    for (size_t _i = 0; _i < n; _i++) kz_record_set(_vals, _keys, 5, _i, k ? k[_i] : NULL, v[_i]);
    return kz_record_create("Token", 5, _keys, _vals);
}

